"""Validate data.json and the files generated by tools/build.py."""
import csv, json, sys
from collections import Counter

PRIMARY = {'derive', 'fork', 'port', 'variant'}
d = json.load(open('data.json'))
t = json.load(open('taxonomy.json'))
err = []
ids = [w['id'] for w in d['works']]
W = {w['id']: w for w in d['works']}
N = {n['id']: n for n in t['nodes']}
for k, c in Counter(ids).items():
    if c > 1: err.append(f'duplicate id {k}')
if set(ids) != set(N): err.append('works and taxonomy nodes differ')
for e in d['edges']:
    for end in (e['source'], e['target']):
        if end not in W: err.append(f'edge endpoint missing: {e}')
    if e['source'] == e['target']: err.append(f'self edge: {e}')
prim = [e for e in d['edges'] if e['relation'] in PRIMARY]
for k, c in Counter(e['target'] for e in prim).items():
    if c > 1: err.append(f'multiple primary parents: {k}')
for n in t['nodes']:
    p = n['primary_parent']
    if p:
        if not any(e['source'] == p and e['target'] == n['id'] and e['relation'] == n['primary_relation'] for e in prim):
            err.append(f'primary parent without edge: {n["id"]}')
        seen, cur = set(), n['id']
        while N[cur]['primary_parent']:
            if cur in seen: err.append(f'cycle at {n["id"]}'); break
            seen.add(cur); cur = N[cur]['primary_parent']
        path = [n['id']]; cur = n['id']
        while N[cur]['primary_parent']: cur = N[cur]['primary_parent']; path.insert(0, cur)
        if path != n['lineage_path'] or n['root_id'] != path[0]: err.append(f'lineage_path mismatch: {n["id"]}')
for r in t['roots']:
    if N[r]['primary_parent']: err.append(f'root has primary parent: {r}')
for e in prim:
    if N[e['target']]['primary_parent'] != e['source']: err.append(f'primary edge not in taxonomy: {e["source"]}->{e["target"]}')
for e in d['edges']:
    if e['relation'] == 'candidate' and N[e['target']]['primary_parent']: err.append(f'candidate target already placed: {e["target"]}')
key = lambda e: (e['source'], e['target'], e['relation'], e['evidence'])
horiz = [e for e in d['edges'] if e['relation'] not in PRIMARY | {'candidate'}]
if sorted(map(key, horiz)) != sorted(map(key, t['horizontal_relations'])): err.append('horizontal_relations out of sync')
if sorted(map(key, [e for e in d['edges'] if e['relation'] == 'candidate'])) != sorted(map(key, t['candidate_relations'])): err.append('candidate_relations out of sync')
rd = lambda p: list(csv.DictReader(open(p, encoding='utf-8-sig')))
EK = ['source', 'target', 'relation', 'confidence', 'evidence', 'notes']
if [tuple(e[k] for k in EK) for e in d['edges']] != [tuple(x[k] for k in EK) for x in rd('edges.csv')]: err.append('edges.csv out of sync')
if [x['id'] for x in rd('works.csv')] != ids: err.append('works.csv ids out of sync')
tr = {(x['source_id'], x['target_id'], x['relation'], x['evidence']) for x in rd('transfers.csv')}
if tr != set(map(key, horiz)): err.append('transfers.csv out of sync')
for x in rd('aliases.csv'):
    if x['work_id'] not in W: err.append(f'alias for unknown id {x["work_id"]}')
cls = Counter(n['classification'] for n in t['nodes'])
s = t['summary']
for k, v in {'all_nodes': len(ids), 'all_relations': len(d['edges']), 'felucca_nodes': cls['felucca-descendant'],
             'primary_edges': len(prim), 'horizontal_edges': len(horiz), 'candidate_edges': len(t['candidate_relations']),
             'unresolved_root_nodes': cls['unplaced'], 'root_nodes': len(t['roots']),
             'aliases': len(rd('aliases.csv'))}.items():
    if s.get(k) != v: err.append(f'summary {k}={s.get(k)} expected {v}')

fel = [n for n in t['nodes'] if n['classification'] == 'felucca-descendant']
sid = lambda i: 'n_' + i.replace(':', '_')
L = ['flowchart LR', '  %% Verified or first-party-claimed primary ancestry; lateral transfers, renamed aliases and merge-back edges are stored separately.']
L += [f'  {sid(n["id"])}["{n["name"]}"]' for n in fel]
L += [f'  {sid(n["primary_parent"])} {"-.->" if n["primary_relation"] == "port" else "-->"} {sid(n["id"])}' for n in fel if n['primary_parent']]
L += ['  classDef root fill:#e4e7eb,stroke:#666,color:#111', '  class n_F_1 root']
mmd = '\n'.join(L) + '\n'
K = {}
for n in fel:
    if n['primary_parent']: K.setdefault(n['primary_parent'], []).append(n)
lab = lambda n: f"'{n['name']} [{n['id']}]'"
def nw(n):
    c = sorted(K.get(n['id'], []), key=lambda x: f"{x['name']} [{x['id']}]".lower())
    return ('(' + ','.join(nw(x) for x in c) + ')' if c else '') + lab(n)
nwk = nw(N['F:1']) + ';\n'
if open('taxonomy.mmd').read() != mmd: err.append('taxonomy.mmd out of date (run tools/build.py)')
if open('lineage.newick').read() != nwk: err.append('lineage.newick out of date (run tools/build.py)')
print('\n'.join(err) or 'OK')
sys.exit(1 if err else 0)
